public:
    int maximumRobots(std::vector<int>& chargeTimes, std::vector<int>& runningCosts, long long budget) {
        std::deque<int> dq;
        int left = 0;
        long long curSum = 0;
        int maxLen = 0;

        for (int right = 0; right < (int)chargeTimes.size(); right++) {
            curSum += runningCosts[right];
            while (!dq.empty() && chargeTimes[dq.back()] <= chargeTimes[right]) {
                dq.pop_back();
            }
            dq.push_back(right);

            while (left <= right && (long long)chargeTimes[dq.front()] + (long long)(right - left + 1) * curSum > budget) {
                if (dq.front() == left) dq.pop_front();
                curSum -= runningCosts[left];
                left++;
            }
            maxLen = std::max(maxLen, right - left + 1);
        }
        return maxLen;
    }
};

class Solution {
    public int maximumRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        java.util.Deque<Integer> dq = new java.util.ArrayDeque<>();
        int left = 0;
        long curSum = 0;
        int maxLen = 0;

        for (int right = 0; right < chargeTimes.length; right++) {
            curSum += runningCosts[right];
            while (!dq.isEmpty() && chargeTimes[dq.peekLast()] <= chargeTimes[right]) {
                dq.pollLast();
            }
            dq.offerLast(right);

            while (left <= right && (long) chargeTimes[dq.peekFirst()] + (long) (right - left + 1) * curSum > budget) {
                if (dq.peekFirst() == left) dq.pollFirst();
                curSum -= runningCosts[left];
                left++;
            }
            maxLen = Math.max(maxLen, right - left + 1);
        }
        return maxLen;
    }
}

